<?php
$folderChildren = [];
foreach ($folders as $folder) { $folderChildren[(int) ($folder['parent_id'] ?? 0)][] = $folder; }
$serviceChildren = [];
foreach ($services as $service) { $serviceChildren[(int) ($service['folder_id'] ?? 0)][] = $service; }
$renderRows = function (int $parent, int $depth) use (&$renderRows, $folderChildren, $serviceChildren, $balanceTypes): void {
    foreach ($folderChildren[$parent] ?? [] as $folder) {
        $id = (int) $folder['id']; ?>
        <tr class="service-tree-row folder-row" data-folder="<?= $id ?>" data-parent="<?= $parent ?>"><td><div class="tree-name" style="--depth:<?= $depth ?>"><button type="button" class="tree-toggle" aria-expanded="true" aria-label="Свернуть папку">−</button><span class="folder-icon">📁</span><strong><?= e($folder['name']) ?></strong></div></td><?php foreach ($balanceTypes as $type): ?><td></td><?php endforeach; ?><td></td><td></td><td></td></tr>
        <?php $renderRows($id, $depth + 1);
    }
    foreach ($serviceChildren[$parent] ?? [] as $service) {
        $details = json_decode($service['service_data'] ?? '', true) ?: [];
        $totals = [];
        foreach ($details['allocations'] ?? [] as $allocation) { foreach ($allocation['balances'] ?? [] as $type => $value) { $totals[$type] = ($totals[$type] ?? 0) + (float) $value; } }
        ?><tr class="service-tree-row service-item" data-parent="<?= $parent ?>" data-service="<?= e(json_encode($service, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP)) ?>"><td><button type="button" class="service-edit tree-name" style="--depth:<?= $depth ?>"><span class="file-icon">▤</span><?= e($service['name']) ?></button></td><?php foreach ($balanceTypes as $type): ?><td><?= isset($totals[$type['id']]) ? e((string) $totals[$type['id']]) : '' ?></td><?php endforeach; ?><td><?= $totals ? e((string) array_sum($totals)) : '' ?></td><td><?= $service['status'] === 'active' ? 'Все' : 'Скрыта' ?></td><td><?= (int) $service['id'] ?></td></tr><?php
    }
};
?>
<section class="section-heading"><div><h2>Услуги и товары</h2><p>Каталог услуг и начислений на балансы курсантов.</p></div></section>
<section class="panel services-panel">
    <div class="services-toolbar"><button type="button" class="button button--primary" id="service-add">＋ Добавить</button><button type="button" class="button button--secondary" id="folder-add">📁 Новая папка</button><label class="services-search"><input id="service-search" placeholder="Поиск по названию"></label><label><input type="checkbox" id="show-inactive"> Скрытые</label></div>
    <div class="services-table-wrap"><table class="services-table"><thead><tr><th>Наименование</th><?php foreach ($balanceTypes as $type): ?><th title="<?= e($type['name']) ?>"><span class="balance-code" style="--chip-color:<?= e($type['color']) ?>"><?= e($type['code']) ?></span></th><?php endforeach; ?><th>Итого</th><th>Учебные классы</th><th>ID</th></tr></thead><tbody><?php $renderRows(0, 0); ?></tbody></table></div>
    <?php if (!$folders && !$services): ?><p class="services-empty">Добавьте папку или услугу, чтобы создать каталог.</p><?php endif; ?>
</section>
<dialog id="folder-dialog" class="service-dialog service-dialog--small"><form method="post" action="<?= e(url('/education/services/folders')) ?>"><?= csrf_field() ?><div class="service-dialog-head"><h3>Новая папка</h3><button type="button" data-close>×</button></div><div class="service-dialog-body"><label>Название <input name="name" required maxlength="190"></label><label>Родительская папка <select name="parent_id"><option value="">Корень</option><?php foreach ($folders as $folder): ?><option value="<?= (int) $folder['id'] ?>"><?= e($folder['name']) ?></option><?php endforeach; ?></select></label></div><footer><button type="button" data-close class="button button--secondary">Отмена</button><button class="button button--primary">Сохранить</button></footer></form></dialog>
<dialog id="service-dialog" class="service-dialog" data-balance-types="<?= e(json_encode(array_map(fn($t) => (int) $t['id'], $balanceTypes))) ?>"><form method="post" id="service-form" action="<?= e(url('/education/services')) ?>"><?= csrf_field() ?><div class="service-dialog-head"><h3>Услуга, товар</h3><button type="button" data-close aria-label="Закрыть">×</button></div><nav class="service-tabs"><button type="button" class="active" data-tab="basic">Основное</button><button type="button" data-tab="balances">Начисления на балансы</button></nav><div class="service-dialog-body" data-panel="basic"><div class="service-form-grid"><label>Тип продукта<select name="type"><option value="service">Услуга</option><option value="product">Товар</option></select></label><label><span>Наименование <b>*</b></span><input name="name" required maxlength="190"></label><label>Код/артикул<input name="code" maxlength="190" placeholder="При наличии"></label><label>Папка<select name="folder_id"><option value="">Корень</option><?php foreach ($folders as $folder): ?><option value="<?= (int) $folder['id'] ?>"><?= e($folder['name']) ?></option><?php endforeach; ?></select></label><label><span>Стоимость, руб. <b>*</b></span><input name="price" type="number" min="0" step="0.01" required value="0"></label><label>Описание<input name="description"></label></div><label class="service-check"><input type="checkbox" name="main_activity" value="1"> Основная деятельность</label><p class="service-hint">Только одна услуга по основной деятельности может быть продана в рамках договора с курсантом</p><label class="service-check"><input type="checkbox" name="available" checked> Услуга/товар доступна для продажи</label><input type="hidden" name="status" value="active"><label class="service-check"><input type="checkbox" name="no_discounts" value="1"> Запретить скидки при продаже</label></div><div class="service-dialog-body" data-panel="balances" hidden><div class="allocation-heading">Схема начислений <button type="button" id="allocation-add" title="Добавить строку">＋</button></div><div class="services-table-wrap"><table class="services-table allocation-table"><thead><tr><th>Сумма внесенных оплат, руб.</th><?php foreach ($balanceTypes as $type): ?><th title="<?= e($type['name']) ?>"><span class="balance-code" style="--chip-color:<?= e($type['color']) ?>"><?= e($type['code']) ?></span></th><?php endforeach; ?><th></th></tr></thead><tbody id="allocation-rows"></tbody></table></div><p class="service-hint">Укажите сумму оплаты и начисления для каждого типа баланса.</p></div><footer><button type="button" data-close class="button button--secondary">Отмена</button><button type="submit" class="button button--primary">Сохранить</button></footer></form></dialog>
